import React, { useState } from 'react';
import SlideCard from './components/SlideCard';
import VerticalNav from './components/VerticalNav';
import ParallaxBg from './components/ParallaxBg';
import TypewriterText from './components/TypewriterText';
import FlipCard from './components/FlipCard';
import AnimatedEmail from './components/AnimatedEmail';
import { Shield, User, AlertTriangle, Mail, Eye, Search, Zap, CheckCircle, Settings, CaseSensitive, Wrench, MessageCircle, Heart, Phone } from 'lucide-react';

const phishingTypes = [
  {
    title: 'Spear Phishing',
    desc: 'Serangan tertarget ke individu tertentu dengan data personal.',
    icon: <Mail className="text-orange-500 w-8 h-8 mb-2" />,
  },
  {
    title: 'Whaling',
    desc: 'Menargetkan eksekutif perusahaan atau VIP.',
    icon: <User className="text-orange-500 w-8 h-8 mb-2" />,
  },
  {
    title: 'Clone Phishing',
    desc: 'Email asli diduplikasi lalu diubah link/lampirannya.',
    icon: <Mail className="text-orange-500 w-8 h-8 mb-2" />,
  },
  {
    title: 'BEC',
    desc: 'Business Email Compromise, penipuan transfer dana.',
    icon: <AlertTriangle className="text-orange-500 w-8 h-8 mb-2" />,
  },
  {
    title: 'Vishing',
    desc: 'Phishing via telepon.',
    icon: <Phone className="text-orange-500 w-8 h-8 mb-2" />,
  },
  {
    title: 'Smishing',
    desc: 'Phishing via SMS.',
    icon: <Mail className="text-orange-500 w-8 h-8 mb-2" />,
  },
];

const slides = [
  {
    id: 'slide1',
    type: 'title',
    title: 'Phishing 101 - Jangan Jadi Korban!',
    subtitle: 'Belajar Mengenali dan Menghindari Serangan Phishing',
    icon: Shield,
    logo: '/logo-hacktiv8.png',
  },
  {
    id: 'slide2',
    type: 'speaker',
    name: 'Kiell Tampubolon',
    role: 'Cybersecurity Engineer, Singapore',
    photo: '/IMG_8642.jpg',
  },
  {
    id: 'slide3',
    type: 'definition',
    title: 'Apa itu Phishing?',
    analogy: 'Penipu berdasi',
    desc: 'Teknik manipulasi sosial untuk mencuri data sensitif melalui email/pesan palsu. 90% serangan cyber dimulai dari phishing (Verizon DBIR).',
    img: 'https://cdn.pixabay.com/photo/2017/01/31/13/14/phishing-2022273_1280.png',
  },
  {
    id: 'slide4',
    type: 'types',
    title: 'Jenis-jenis Phishing',
    types: phishingTypes,
  },
  {
    id: 'slide5',
    type: 'signs',
    title: 'Ciri-ciri Email Phishing',
  },
  {
    id: 'slide6',
    type: 'demo',
    title: 'Demo Analisis Email',
    video: 'https://www.youtube.com/embed/1c1w0pQOa2Q',
    sources: [
      { name: 'VirusTotal', url: 'https://www.virustotal.com/' },
      { name: 'MXToolbox', url: 'https://mxtoolbox.com/' },
      { name: 'Email Header Analyzer', url: 'https://mxtoolbox.com/EmailHeaders.aspx' },
    ],
  },
  {
    id: 'slide7',
    type: 'simulation',
    title: 'Simulasi Kirim Phishing Email',
    desc: 'Gunakan GoPhish / Template Demo. Disclaimer: Edukasi saja, tidak dikirim ke peserta.',
    sources: [
      { name: 'GoPhish', url: 'https://getgophish.com/' },
    ],
  },
  {
    id: 'slide8',
    type: 'tips',
    title: 'Tips Mendeteksi Phishing',
    tips: [
      'Hover sebelum klik',
      'Jangan tergesa-gesa',
      'Periksa domain/email',
      'Verifikasi ke sumber resmi',
    ],
  },
  {
    id: 'slide9',
    type: 'protection',
    title: 'Strategi Perlindungan',
    points: [
      'Untuk Individu: MFA, password manager, awareness',
      'Untuk Perusahaan: Filter email, DMARC/SPF, simulasi phishing berkala',
    ],
  },
  {
    id: 'slide10',
    type: 'case',
    title: 'Studi Kasus Nyata',
    cases: [
      'BEC rugi $10 juta',
      'Phishing LinkedIn rekrutmen palsu',
    ],
  },
  {
    id: 'slide11',
    type: 'tools',
    title: 'Tools Gratis untuk Melindungi Diri',
    tools: [
      { name: 'VirusTotal', url: 'https://www.virustotal.com/' },
      { name: 'HaveIBeenPwned', url: 'https://haveibeenpwned.com/' },
      { name: 'Bitwarden', url: 'https://bitwarden.com/' },
      { name: 'Email Header Analyzer', url: 'https://mxtoolbox.com/EmailHeaders.aspx' },
    ],
  },
  {
    id: 'slide12',
    type: 'qna',
    title: 'Tanya Jawab',
    desc: 'Silakan ajukan pertanyaan, bahkan yang paling sederhana. Karena hacker tidak butuh celah besar, cukup satu klik dari Anda.',
  },
  {
    id: 'slide13',
    type: 'closing',
    title: 'Penutup & CTA',
    points: [
      'Phishing bisa dicegah',
      'Edukasi & kesadaran adalah kunci',
      'Jangan klik sebelum yakin!',
    ],
    desc: 'Hari ini, mulai cek ulang email yang Anda terima. Jangan mudah percaya, jangan panik, selalu verifikasi.',
  },
];

function App() {
  const [current, setCurrent] = useState(0);
  const slide = slides[current];

  // Fullscreen handler
  const handleFullscreen = () => {
    const elem = document.documentElement;
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else {
      elem.requestFullscreen();
    }
  };

  return (
    <div className="min-h-screen w-full gradient-bg flex items-center justify-center relative overflow-x-hidden font-poppins">
      {/* Logo Hacktiv8 kanan atas, selalu tampil */}
      <img src="/logo-hacktiv8.png" alt="Hacktiv8 Logo" className="slide-logo" />
      {/* Slide Content */}
      <div className="slide-container">
        <SlideCard>
          {/* Slide 1: Judul */}
          {slide.type === 'title' && (
            <div className="slide-content flex flex-col items-center gap-4">
              <Shield size={72} className="text-orange-600 drop-shadow-lg animate-bounce mb-2" />
              <h1 className="slide-title">
                <TypewriterText text={slide.title} speed={40} />
              </h1>
              <h2 className="slide-subtitle">
                <TypewriterText text={slide.subtitle} speed={20} />
              </h2>
            </div>
          )}
          {/* Slide 2: Tentang Pembicara */}
          {slide.type === 'speaker' && (
            <div className="slide-content flex flex-col md:flex-row items-center gap-8">
              <div className="flex-shrink-0">
                <img src={slide.photo} alt="Foto Pembicara" className="w-32 h-32 md:w-40 md:h-40 rounded-full object-cover border-4 border-orange-200 shadow-lg" />
              </div>
              <div className="flex-1 text-left md:pl-6">
                <h2 className="slide-title mb-2">{slide.name}</h2>
                <div className="slide-subtitle mb-2">{slide.role}</div>
                <div className="slide-text text-white/90">Cybersecurity enthusiast, passionate about phishing awareness and digital safety.</div>
              </div>
            </div>
          )}
          {/* Slide 3: Apa itu Phishing */}
          {slide.type === 'definition' && (
            <div className="slide-content flex flex-col md:flex-row items-center gap-8">
              <img src={slide.img} alt="Ilustrasi Phishing" className="w-32 h-32 object-contain mx-auto mb-4 md:mb-0" />
              <div className="flex-1 text-left">
                <h2 className="slide-title mb-2">{slide.title}</h2>
                <div className="slide-text mb-2">
                  <TypewriterText text={slide.desc} speed={20} />
                </div>
                <div className="text-orange-200 italic text-lg">Analog: <span className="font-bold">{slide.analogy}</span> <span role="img" aria-label="tie">👔</span></div>
              </div>
            </div>
          )}
          {/* Slide 4: Jenis-jenis Phishing */}
          {slide.type === 'types' && (
            <div className="slide-content grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
              {slide.types.map((t, idx) => (
                <FlipCard
                  key={t.title}
                  front={<div className="flex flex-col items-center"><div>{t.icon}</div><div className="font-bold text-orange-700 text-lg">{t.title}</div></div>}
                  back={<div className="text-white text-center text-sm p-2">{t.desc}</div>}
                />
              ))}
            </div>
          )}
          {/* Slide 5: Ciri-ciri Email Phishing */}
          {slide.type === 'signs' && (
            <div className="slide-content flex flex-col items-center">
              <AnimatedEmail />
            </div>
          )}
          {/* Slide 6: Demo Analisis Email */}
          {slide.type === 'demo' && (
            <div className="slide-content flex flex-col items-center">
              <div className="w-full aspect-video rounded-xl overflow-hidden shadow-lg mb-4">
                <iframe
                  src={slide.video}
                  title="Demo Analisis Email"
                  frameBorder="0"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                  className="w-full h-full"
                ></iframe>
              </div>
              <div className="text-white/90 text-center mb-2">Contoh analisis email phishing menggunakan tools online.</div>
              <div className="flex flex-wrap gap-4 justify-center mt-2">
                {slide.sources.map((src) => (
                  <a key={src.name} href={src.url} target="_blank" rel="noopener noreferrer" className="bg-orange-600 hover:bg-orange-700 text-white px-4 py-2 rounded-full font-bold shadow transition">{src.name}</a>
                ))}
              </div>
            </div>
          )}
          {/* Slide 7: Simulasi Kirim Phishing Email */}
          {slide.type === 'simulation' && (
            <div className="slide-content flex flex-col items-center">
              <Zap size={48} className="text-orange-500 mb-4 animate-pulse" />
              <h2 className="slide-title mb-2">{slide.title}</h2>
              <div className="slide-text text-white/90 text-center mb-2">{slide.desc}</div>
              <div className="flex flex-wrap gap-4 justify-center mt-2">
                {slide.sources.map((src) => (
                  <a key={src.name} href={src.url} target="_blank" rel="noopener noreferrer" className="bg-orange-600 hover:bg-orange-700 text-white px-4 py-2 rounded-full font-bold shadow transition">{src.name}</a>
                ))}
              </div>
            </div>
          )}
          {/* Slide 8: Tips Mendeteksi Phishing */}
          {slide.type === 'tips' && (
            <div className="slide-content flex flex-col items-center">
              <CheckCircle size={48} className="text-orange-400 mb-4 animate-bounce" />
              <h2 className="slide-title mb-2">{slide.title}</h2>
              <ul className="text-white/90 text-left space-y-2">
                {slide.tips.map((tip, idx) => (
                  <li key={tip} className="hover:text-orange-300 transition-colors font-bold flex items-center gap-2"><span>•</span>{tip}</li>
                ))}
              </ul>
            </div>
          )}
          {/* Slide 9: Strategi Perlindungan */}
          {slide.type === 'protection' && (
            <div className="slide-content flex flex-col items-center">
              <Settings size={48} className="text-orange-400 mb-4 animate-spin-slow" />
              <h2 className="slide-title mb-2">{slide.title}</h2>
              <ul className="text-white/90 text-left space-y-2">
                {slide.points.map((pt, idx) => (
                  <li key={pt} className="hover:text-orange-300 transition-colors font-bold flex items-center gap-2"><span>•</span>{pt}</li>
                ))}
              </ul>
            </div>
          )}
          {/* Slide 10: Studi Kasus Nyata */}
          {slide.type === 'case' && (
            <div className="slide-content flex flex-col items-center">
              <CaseSensitive size={48} className="text-orange-400 mb-4 animate-pulse" />
              <h2 className="slide-title mb-2">{slide.title}</h2>
              <ul className="text-white/90 text-left space-y-2">
                {slide.cases.map((c, idx) => (
                  <li key={c} className="hover:text-orange-300 transition-colors font-bold flex items-center gap-2"><span>•</span>{c}</li>
                ))}
              </ul>
            </div>
          )}
          {/* Slide 11: Tools Gratis untuk Melindungi Diri */}
          {slide.type === 'tools' && (
            <div className="slide-content flex flex-col items-center">
              <Wrench size={48} className="text-orange-400 mb-4 animate-spin" />
              <h2 className="slide-title mb-2">{slide.title}</h2>
              <ul className="text-white/90 text-left space-y-2">
                {slide.tools.map((tool, idx) => (
                  <li key={tool.name} className="hover:text-orange-300 transition-colors font-bold flex items-center gap-2">
                    <a href={tool.url} target="_blank" rel="noopener noreferrer" className="underline underline-offset-2">{tool.name}</a>
                  </li>
                ))}
              </ul>
            </div>
          )}
          {/* Slide 12: Tanya Jawab */}
          {slide.type === 'qna' && (
            <div className="slide-content flex flex-col items-center">
              <MessageCircle size={48} className="text-orange-400 mb-4 animate-bounce" />
              <h2 className="slide-title mb-2">{slide.title}</h2>
              <div className="slide-text text-white/90 text-center">{slide.desc}</div>
            </div>
          )}
          {/* Slide 13: Penutup & CTA */}
          {slide.type === 'closing' && (
            <div className="slide-content flex flex-col items-center">
              <Heart size={48} className="text-orange-400 mb-4 animate-bounce" />
              <h2 className="slide-title mb-2">{slide.title}</h2>
              <ul className="text-white/90 text-left space-y-2 mb-2">
                {slide.points.map((pt, idx) => (
                  <li key={pt} className="hover:text-orange-300 transition-colors font-bold flex items-center gap-2"><span>•</span>{pt}</li>
                ))}
              </ul>
              <div className="slide-text text-white/90 text-center">{slide.desc}</div>
            </div>
          )}
        </SlideCard>
      </div>
      {/* Vertical Navigation */}
      <VerticalNav
        current={current}
        total={slides.length}
        onPrev={() => setCurrent((c) => Math.max(0, c - 1))}
        onNext={() => setCurrent((c) => Math.min(slides.length - 1, c + 1))}
        onFullscreen={handleFullscreen}
      />
    </div>
  );
}

export default App;
